def equilibrium_branches(parameters: Iterable[float]) -> list[tuple[float, tuple[float, ...]]]:
    """Enumerate all real equilibria of mu - x^2 for each parameter."""
    result: list[tuple[float, tuple[float, ...]]] = []
    for mu in parameters:
        if mu < 0.0:
            roots: tuple[float, ...] = ()
        elif mu == 0.0:
            roots = (0.0,)
        else:
            root = sqrt(mu)
            roots = (-root, root)
        result.append((mu, roots))
    return result

